library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

package cordic_pipeline_pkg is

   constant ATAN_TABLE_WIDTH : natural := 32;
   constant ATAN_TABLE_SIZE  : natural := 32;
   constant MAX_RM_GAIN      : natural := 12;

   type atan_table_t is array( 0 to ATAN_TABLE_SIZE-1 ) of unsigned( ATAN_TABLE_WIDTH-1 downto 0 );

   type rm_gain_term_t is record
      add   : boolean;
      shift : natural;
   end record rm_gain_term_t;

   type rm_gain_terms_t is array( 1 to MAX_RM_GAIN, 1 to MAX_RM_GAIN ) of rm_gain_term_t;

   constant ADD     : boolean        := true;
   constant SUB     : boolean        := false;
   constant NO_TERM : rm_gain_term_t := ( ADD, 0 );

   -- round( atan( 2**-i ) / ( 2*pi ) * 2**ATAN_TABLE_WIDTH )
   constant ATAN_TABLE : atan_table_t := (
      x"20000000",
      x"12E4051E",
      x"09FB385B",
      x"051111D4",
      x"028B0D43",
      x"0145D7E1",
      x"00A2F61E",
      x"00517C55",
      x"0028BE53",
      x"00145F2F",
      x"000A2F98",
      x"000517CC",
      x"00028BE6",
      x"000145F3",
      x"0000A2FA",
      x"0000517D",
      x"000028BE",
      x"0000145F",
      x"00000A30",
      x"00000518",
      x"0000028C",
      x"00000146",
      x"000000A3",
      x"00000051",
      x"00000029",
      x"00000014",
      x"0000000A",
      x"00000005",
      x"00000003",
      x"00000001",
      x"00000001",
      x"00000000"
   );

   -- Row R holds the R terms of RM_GAIN = R: ( ADD or SUB, shift ) of v >> shift.
   constant RM_GAIN_TERMS : rm_gain_terms_t := (
      1  => ( ( ADD,  1 ), others => NO_TERM ),
      2  => ( ( ADD,  1 ), ( SUB,  4 ), others => NO_TERM ),
      3  => ( ( ADD,  1 ), ( ADD,  3 ), ( SUB,  5 ), others => NO_TERM ),
      4  => ( ( ADD,  1 ), ( ADD,  3 ), ( SUB,  6 ), ( SUB,  8 ), others => NO_TERM ),
      5  => ( ( ADD,  1 ), ( ADD,  3 ), ( SUB,  6 ), ( SUB,  9 ), ( SUB, 12 ), others => NO_TERM ),
      6  => ( ( ADD,  1 ), ( ADD,  3 ), ( SUB,  6 ), ( SUB,  9 ), ( SUB, 13 ), ( SUB, 14 ), others => NO_TERM ),
      7  => ( ( ADD,  1 ), ( ADD,  3 ), ( SUB,  6 ), ( SUB,  9 ), ( SUB, 13 ), ( SUB, 14 ),
              ( SUB, 17 ), others => NO_TERM ),
      8  => ( ( ADD,  1 ), ( ADD,  3 ), ( SUB,  6 ), ( SUB,  9 ), ( SUB, 13 ), ( SUB, 14 ),
              ( ADD, 16 ), ( SUB, 19 ), others => NO_TERM ),
      9  => ( ( ADD,  1 ), ( ADD,  3 ), ( SUB,  6 ), ( SUB,  9 ), ( SUB, 13 ), ( SUB, 14 ),
              ( ADD, 16 ), ( SUB, 20 ), ( SUB, 22 ), others => NO_TERM ),
      10 => ( ( ADD,  1 ), ( ADD,  3 ), ( SUB,  6 ), ( SUB,  9 ), ( SUB, 13 ), ( SUB, 14 ),
              ( ADD, 16 ), ( SUB, 20 ), ( SUB, 23 ), ( SUB, 25 ), others => NO_TERM ),
      11 => ( ( ADD,  1 ), ( ADD,  3 ), ( SUB,  6 ), ( SUB,  9 ), ( SUB, 13 ), ( SUB, 14 ),
              ( ADD, 16 ), ( SUB, 20 ), ( SUB, 23 ), ( SUB, 26 ), ( SUB, 27 ), others => NO_TERM ),
      12 => ( ( ADD,  1 ), ( ADD,  3 ), ( SUB,  6 ), ( SUB,  9 ), ( SUB, 13 ), ( SUB, 14 ),
              ( ADD, 16 ), ( SUB, 20 ), ( SUB, 23 ), ( SUB, 26 ), ( SUB, 28 ), ( SUB, 29 ) )
   );

   function cordic_pipeline_latency( N_ITER, RM_GAIN : natural ) return natural;

end package cordic_pipeline_pkg;

package body cordic_pipeline_pkg is

   function cordic_pipeline_latency( N_ITER, RM_GAIN : natural ) return natural is
   begin
      return 1 + N_ITER + RM_GAIN;
   end function cordic_pipeline_latency;

end package body cordic_pipeline_pkg;
